// Title: Add a custom CSS class to the <body> tag after converting an Excel workbook to HTML with Aspose.Cells for .NET (C#)
// Common Searches: C# how to append a CSS class to the body tag of HTML generated by Aspose.Cells | post‑process Aspose.Cells HTML output to include a custom body class attribute | add custom styling to Aspose.Cells SaveFormat.Html result using regex in .NET | modify the <body> element of an Excel‑to‑HTML conversion with Aspose.Cells C#
// Tags: add body class after Aspose.Cells HTML export | post‑process generated HTML with C# regex Aspose.Cells | custom CSS styling for Aspose.Cells SaveFormat.Html output | modify HTML body attribute in .NET after workbook.Save | Aspose.Cells HTML conversion custom class attribute

using System;
using System.IO;
using System.Text.RegularExpressions;
using Aspose.Cells;

// The example loads an Excel workbook, saves it as HTML using Aspose.Cells, reads the generated file, uses a regular expression to locate the opening <body> tag, and either appends a custom CSS class to an existing class attribute or adds a new class attribute, then writes the updated HTML back to disk.
class HtmlBodyClassAppender
{
    static void Main()
    {
        // Load an existing Excel workbook (replace with your actual file path)
        var workbook = new Workbook("input.xlsx");   // load-workbook rule

        // Convert the workbook to HTML (replace with your desired output path)
        workbook.Save("output.html", SaveFormat.Html);   // save-html rule

        // Read the generated HTML content
        string html = File.ReadAllText("output.html");

        // Define the custom CSS class to add
        const string customClass = "my-custom-style";

        // Regex to find the opening <body> tag (with or without existing attributes)
        var bodyTagPattern = new Regex(@"<body([^>]*)>", RegexOptions.IgnoreCase);
        html = bodyTagPattern.Replace(html, match =>
        {
            string existingAttributes = match.Groups[1].Value;

            // Check if a class attribute already exists
            var classAttrPattern = new Regex(@"class\s*=\s*[""']([^""']*)[""']", RegexOptions.IgnoreCase);
            var classMatch = classAttrPattern.Match(existingAttributes);

            if (classMatch.Success)
            {
                // Append the custom class to the existing class list
                string existingClasses = classMatch.Groups[1].Value;
                string newClasses = existingClasses + " " + customClass;
                // Replace the old class attribute with the new one
                string updatedAttributes = classAttrPattern.Replace(existingAttributes,
                    $"class=\"{newClasses.Trim()}\"");
                return $"<body{updatedAttributes}>";
            }
            else
            {
                // No class attribute present; add one
                return $"<body{existingAttributes} class=\"{customClass}\">";
            }
        }, 1); // Replace only the first occurrence

        // Write the modified HTML back to the file (or to a new file if preferred)
        File.WriteAllText("output.html", html);
    }
}
